package com.skyclone.mod.extras;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The module's data (generated by tools/gen/extras/gen_extras.py), as plain classes. No Bukkit, so the unit
 * tests read the very same files the server does.
 */
final class Catalog {

    static final class Song {
        String id, name, difficulty, notes;
        int intelligence, sbxp, beatTicks;
    }

    static final class Phone {
        String id;
        int contacts, discs;
        List<String> features = new ArrayList<>();
        boolean has(String f) { return features != null && features.contains(f); }
    }

    static final class Req {
        Map<String, Integer> items = new LinkedHashMap<>();
        long coins;
        String key;
        Map<String, Long> essence = new LinkedHashMap<>();
        String contact;
        String set;
        boolean keep;
        boolean none() {
            return (items == null || items.isEmpty()) && coins <= 0 && key == null
                    && (essence == null || essence.isEmpty()) && contact == null && set == null;
        }
    }

    static final class Contact {
        String id, ref, command, tip;
        List<String> npcs = new ArrayList<>();
        List<String> args = new ArrayList<>();
        List<String> lines = new ArrayList<>();
        Req req = new Req();
    }

    /** {@code {npc:<npc id>}} in a contact's phone line; filled with that NPC's live display name. */
    static final java.util.regex.Pattern NPC_REF = java.util.regex.Pattern.compile("\\{npc:([a-z0-9_]+)\\}");

    /**
     * Playtest wave 5: a phone line that points the caller at ANOTHER NPC names it through {@code {npc:<id>}} rather
     * than a typed name, so a rename in that NPC's module can never leave the line naming someone who does not exist.
     * {@code names} maps an NPC id to its colourless display name, or null when unknown (then the id is title-cased).
     */
    static String fillLine(String line, java.util.function.Function<String, String> names) {
        if (line == null || line.indexOf('{') < 0) return line;
        java.util.regex.Matcher m = NPC_REF.matcher(line);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            String id = m.group(1);
            String n = names == null ? null : names.apply(id);
            if (n == null || n.isBlank()) {
                String bare = id.startsWith("shops_") ? id.substring(6) : id;
                StringBuilder t = new StringBuilder();
                for (String w : bare.split("_")) {
                    if (w.isEmpty()) continue;
                    if (t.length() > 0) t.append(' ');
                    t.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1));
                }
                n = t.toString();
            }
            m.appendReplacement(out, java.util.regex.Matcher.quoteReplacement(n));
        }
        m.appendTail(out);
        return out.toString();
    }

    static final class Perk {
        String type, skill, text;
        double value;
    }

    static final class Component {
        String id, name, stat;
        long coins;
        double value;
        int sbxp;
        Map<String, Integer> items = new LinkedHashMap<>();
    }

    static final class Project {
        String id, name, icon;
        int goal;
        List<String> desc = new ArrayList<>();
        Perk perk;
        List<Component> components = new ArrayList<>();
        Component component(String cid) {
            for (Component c : components) if (c.id.equals(cid)) return c;
            return null;
        }
    }

    static final class Skin {
        String id, rarity;
        int gems, stock;
        List<String> targets = new ArrayList<>();
    }

    final Map<String, Song> songs = new LinkedHashMap<>();
    final Map<String, Phone> phones = new LinkedHashMap<>();
    final Map<String, Contact> contacts = new LinkedHashMap<>();
    final Map<String, Project> projects = new LinkedHashMap<>();
    final Map<String, Skin> skins = new LinkedHashMap<>();

    static Catalog load() {
        Catalog c = new Catalog();
        for (Song s : Catalog.<Song>read("songs.json", new TypeToken<List<Song>>() {}.getType())) c.songs.put(s.id, s);
        for (Phone s : Catalog.<Phone>read("phones.json", new TypeToken<List<Phone>>() {}.getType())) c.phones.put(s.id, s);
        for (Contact s : Catalog.<Contact>read("contacts.json", new TypeToken<List<Contact>>() {}.getType())) {
            if (s.req == null) s.req = new Req();
            c.contacts.put(s.id, s);
        }
        for (Project s : Catalog.<Project>read("city_projects.json", new TypeToken<List<Project>>() {}.getType())) c.projects.put(s.id, s);
        for (Skin s : Catalog.<Skin>read("firesales.json", new TypeToken<List<Skin>>() {}.getType())) c.skins.put(s.id, s);
        return c;
    }

    private static <T> List<T> read(String file, Type type) {
        try (InputStream in = Catalog.class.getResourceAsStream("/data/extras/" + file)) {
            if (in == null) throw new IllegalStateException("missing data/extras/" + file);
            try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                List<T> l = new Gson().fromJson(r, type);
                return l == null ? List.of() : l;
            }
        } catch (java.io.IOException e) {
            throw new IllegalStateException("cannot read data/extras/" + file, e);
        }
    }

    /** Contact whose id OR one of whose NPC ids is {@code key}. */
    Contact contact(String key) {
        if (key == null) return null;
        Contact c = contacts.get(key);
        if (c != null) return c;
        for (Contact x : contacts.values()) if (x.npcs.contains(key)) return x;
        return null;
    }

    /** Contact slots for a phone model and a number of Contacts Trio uses (+3 each, at most 25 uses). */
    static int capacity(Phone phone, int trios) {
        if (phone == null) return 0;
        return phone.contacts + 3 * Math.max(0, Math.min(25, trios));
    }
}
